const MIME_TO_EXT_KEYS = [_][]const u8{ "image/jpeg", "image/png", "image/webp", "image/gif" };
const MIME_TO_EXT_VALS = [_][]const u8{ ".jpg", ".png", ".webp", ".gif" };
const EXT_TO_MIME_KEYS = [_][]const u8{ ".jpg", ".png", ".webp", ".gif" };
const EXT_TO_MIME_VALS = [_][]const u8{ "image/jpeg", "image/png", "image/webp", "image/gif" };

const LogLevel = enum { info, warn, err };

var global_allocator: Allocator = undefined;
var log_mutex: Mutex = .{};

fn log(level: LogLevel, comptime format: []const u8, args: anytype) void {
    log_mutex.lock();
    defer log_mutex.unlock();
    const stderr = std.io.getStdErr().writer();
    const now = time.timestamp();
    switch (level) {
        .info => stderr.print("{d} INFO {s}\n", .{ now, fmt.comptimePrint(format, args) }) catch {},
        .warn => stderr.print("{d} WARN {s}\n", .{ now, fmt.comptimePrint(format, args) }) catch {},
        .err => stderr.print("{d} ERROR {s}\n", .{ now, fmt.comptimePrint(format, args) }) catch {},
    }
}

fn logFmt(level: LogLevel, comptime format: []const u8, args: anytype) void {
    log_mutex.lock();
    defer log_mutex.unlock();
    const stderr = std.io.getStdErr().writer();
    const now = time.timestamp();
    const prefix = switch (level) {
        .info => "INFO",
        .warn => "WARN",
        .err => "ERROR",
    };
    stderr.print("{d} {s} ", .{ now, prefix }) catch {};
    stderr.print(format, args) catch {};
    stderr.print("\n", .{}) catch {};
}

fn getEnv(allocator: Allocator, key: []const u8, default_val: []const u8) []const u8 {
    const val = std.process.getEnvVarOwned(allocator, key) catch return default_val;
    return val;
}

fn mimeToExt(mime: []const u8) []const u8 {
    for (MIME_TO_EXT_KEYS, 0..) |k, i| {
        if (mem.eql(u8, k, mime)) return MIME_TO_EXT_VALS[i];
    }
    return ".bin";
}

fn extToMime(ext: []const u8) []const u8 {
    for (EXT_TO_MIME_KEYS, 0..) |k, i| {
        if (mem.eql(u8, k, ext)) return EXT_TO_MIME_VALS[i];
    }
    return "application/octet-stream";
}

fn isAllowedMime(mime: []const u8) bool {
    for (ALLOWED_IMAGE_MIMES) |m| {
        if (mem.eql(u8, m, mime)) return true;
    }
    return false;
}

fn isAllowedAspectRatio(ar: []const u8) bool {
    for (ALLOWED_ASPECT_RATIOS) |a| {
        if (mem.eql(u8, a, ar)) return true;
    }
    return false;
}

fn isDeepSearchType(t: []const u8) bool {
    for (DEEP_SEARCH_TYPES) |d| {
        if (mem.eql(u8, d, t)) return true;
    }
    return false;
}

const Base64Error = error{ InvalidChar, InvalidPadding, InvalidLength, EmptyInput };

fn base64Decode(allocator: Allocator, input: []const u8) ![]u8 {
    var cleaned = ArrayList(u8).init(allocator);
    defer cleaned.deinit();
    for (input) |c| {
        if (c != ' ' and c != '\n' and c != '\r' and c != '\t') {
            try cleaned.append(c);
        }
    }
    var s = cleaned.items;
    if (s.len == 0) return Base64Error.EmptyInput;
    var urlsafe = false;
    for (s) |c| {
        if (c == '-' or c == '_') {
            urlsafe = true;
            break;
        }
    }
    var padded = ArrayList(u8).init(allocator);
    defer padded.deinit();
    try padded.appendSlice(s);
    const rem = s.len % 4;
    if (rem != 0) {
        var i: usize = 0;
        while (i < 4 - rem) : (i += 1) {
            try padded.append('=');
        }
    }
    s = padded.items;
    if (urlsafe) {
        const decoder = std.base64.url_safe.Decoder;
        const out_len = try decoder.calcSizeForSlice(s);
        const out = try allocator.alloc(u8, out_len);
        try decoder.decode(out, s);
        return out;
    } else {
        const decoder = std.base64.standard.Decoder;
        const out_len = try decoder.calcSizeForSlice(s);
        const out = try allocator.alloc(u8, out_len);
        try decoder.decode(out, s);
        return out;
    }
}

fn base64Encode(allocator: Allocator, input: []const u8) ![]u8 {
    const encoder = std.base64.standard.Encoder;
    const out_len = encoder.calcSize(input.len);
    const out = try allocator.alloc(u8, out_len);
    _ = encoder.encode(out, input);
    return out;
}

fn stripB64Prefix(allocator: Allocator, raw: []const u8) !struct { stripped: []u8, decoded: []u8 } {
    if (raw.len == 0) return Base64Error.EmptyInput;
    var data = raw;
    if (mem.indexOf(u8, data, ",")) |comma_idx| {
        data = data[comma_idx + 1 ..];
    }
    var cleaned = ArrayList(u8).init(allocator);
    defer cleaned.deinit();
    for (data) |c| {
        if (c != ' ' and c != '\n' and c != '\r' and c != '\t') {
            try cleaned.append(c);
        }
    }
    if (cleaned.items.len == 0) return Base64Error.EmptyInput;
    const stripped = try allocator.dupe(u8, cleaned.items);
    const decoded = try base64Decode(allocator, stripped);
    return .{ .stripped = stripped, .decoded = decoded };
}

const ImageFormat = struct {
    mime: []const u8,
    ext: []const u8,
};

fn detectImageFormat(data: []const u8) ImageFormat {
    if (data.len >= 8 and mem.eql(u8, data[0..8], "\x89PNG\r\n\x1a\n")) {
        return .{ .mime = "image/png", .ext = ".png" };
    }
    if (data.len >= 2 and data[0] == 0xff and data[1] == 0xd8) {
        return .{ .mime = "image/jpeg", .ext = ".jpg" };
    }
    if (data.len >= 12 and mem.eql(u8, data[0..4], "RIFF") and mem.eql(u8, data[8..12], "WEBP")) {
        return .{ .mime = "image/webp", .ext = ".webp" };
    }
    if (data.len >= 6 and (mem.eql(u8, data[0..6], "GIF87a") or mem.eql(u8, data[0..6], "GIF89a"))) {
        return .{ .mime = "image/gif", .ext = ".gif" };
    }
    return .{ .mime = "application/octet-stream", .ext = "" };
}

const NormalizedImage = struct {
    data: []u8,
    bytes: []u8,
    media_type: []const u8,
    allocator: Allocator,

    fn deinit(self: *NormalizedImage) void {
        self.allocator.free(self.data);
        self.allocator.free(self.bytes);
    }
};

fn normalizeInputImage(allocator: Allocator, data: []const u8, media_type: []const u8) !NormalizedImage {
    const result = try stripB64Prefix(allocator, data);
    if (result.decoded.len > MAX_IMAGE_BYTES) {
        allocator.free(result.stripped);
        allocator.free(result.decoded);
        return error.ImageTooLarge;
    }
    const fmt_info = detectImageFormat(result.decoded);
    if (!isAllowedMime(fmt_info.mime)) {
        allocator.free(result.stripped);
        allocator.free(result.decoded);
        return error.UnsupportedImageFormat;
    }
    if (!mem.eql(u8, fmt_info.mime, media_type)) {
        allocator.free(result.stripped);
        allocator.free(result.decoded);
        return error.MediaTypeMismatch;
    }
    return NormalizedImage{
        .data = result.stripped,
        .bytes = result.decoded,
        .media_type = fmt_info.mime,
        .allocator = allocator,
    };
}

const MessagePart = union(enum) {
    text: struct { text: []u8 },
    image_url: struct { url: []u8, detail: []u8 },
    image_ref: struct { key: []u8, media_type: []u8 },
    image_inline: struct { data: []u8, media_type: []u8 },
    unknown: struct { raw: []u8 },
};

const ToolCall = struct {
    id: []u8,
    type_: []u8,
    name: []u8,
    arguments: []u8,
    allocator: Allocator,

    fn deinit(self: *ToolCall) void {
        self.allocator.free(self.id);
        self.allocator.free(self.type_);
        self.allocator.free(self.name);
        self.allocator.free(self.arguments);
    }
};

const Message = struct {
    role: []u8,
    content_str: ?[]u8,
    content_parts: ?ArrayList(MessagePart),
    tool_calls: ?ArrayList(ToolCall),
    tool_call_id: ?[]u8,
    allocator: Allocator,

    fn deinit(self: *Message) void {
        self.allocator.free(self.role);
        if (self.content_str) |s| self.allocator.free(s);
        if (self.content_parts) |*parts| {
            for (parts.items) |*part| {
                switch (part.*) {
                    .text => |*t| self.allocator.free(t.text),
                    .image_url => |*iu| {
                        self.allocator.free(iu.url);
                        self.allocator.free(iu.detail);
                    },
                    .image_ref => |*ir| {
                        self.allocator.free(ir.key);
                        self.allocator.free(ir.media_type);
                    },
                    .image_inline => |*ii| {
                        self.allocator.free(ii.data);
                        self.allocator.free(ii.media_type);
                    },
                    .unknown => |*u| self.allocator.free(u.raw),
                }
            }
            parts.deinit();
        }
        if (self.tool_calls) |*tcs| {
            for (tcs.items) |*tc| tc.deinit();
            tcs.deinit();
        }
        if (self.tool_call_id) |tid| self.allocator.free(tid);
    }

    fn charSize(self: *const Message) usize {
        var total: usize = self.role.len + 32;
        if (self.content_str) |s| {
            total += s.len;
        } else if (self.content_parts) |parts| {
            for (parts.items) |part| {
                switch (part) {
                    .text => |t| total += t.text.len,
                    .image_url => |iu| total += iu.url.len + iu.detail.len + 32,
                    .image_ref => |ir| total += ir.key.len + ir.media_type.len + 32,
                    .image_inline => |ii| total += ii.data.len + ii.media_type.len + 32,
                    .unknown => |u| total += u.raw.len,
                }
            }
        }
        if (self.tool_calls) |tcs| {
            for (tcs.items) |tc| {
                total += tc.id.len + tc.name.len + tc.arguments.len + 64;
            }
        }
        if (self.tool_call_id) |tid| total += tid.len;
        return total;
    }
};

const Session = struct {
    messages: ArrayList(Message),
    created_at: i64,
