                            found_colon = true;
                            i += 1;
                            continue;
                        }
                        if (found_colon) {
                            if (stripped[i] == '"') {
                                i += 1;
                                while (i < stripped.len and stripped[i] != '"') {
                                    if (stripped[i] == '\\') i += 1;
                                    i += 1;
                                }
