const RateLimiter = struct {
    max_per_second: usize,
    timestamps: ArrayList(i64),
    mutex: Mutex,

    fn init(allocator: Allocator, max_per_second: usize) RateLimiter {
        return RateLimiter{
            .max_per_second = max_per_second,
            .timestamps = ArrayList(i64).init(allocator),
            .mutex = .{},
        };
    }

    fn deinit(self: *RateLimiter) void {
        self.timestamps.deinit();
    }

    fn acquire(self: *RateLimiter) void {
        while (true) {
            self.mutex.lock();
            const now_ns = time.nanoTimestamp();
            const now_s = @divTrunc(now_ns, time.ns_per_s);
            var i: usize = 0;
            while (i < self.timestamps.items.len) {
                if (now_s - self.timestamps.items[i] >= 1) {
                    _ = self.timestamps.orderedRemove(i);
                } else {
                    i += 1;
                }
            }
            if (self.timestamps.items.len < self.max_per_second) {
                self.timestamps.append(now_s) catch {};
                self.mutex.unlock();
                return;
            }
            self.mutex.unlock();
            time.sleep(50 * time.ns_per_ms);
        }
    }
};

