fn isDeleted(sid: []const u8) bool {
    deleted_sessions_mutex.lock();
    defer deleted_sessions_mutex.unlock();
    if (deleted_sessions.get(sid)) |deleted_at| {
        const now = time.timestamp();
        if (now - deleted_at > DELETED_SESSION_TTL) return false;
        return true;
    }
    return false;
}

fn markDeleted(allocator: Allocator, sid: []const u8) !void {
    deleted_sessions_mutex.lock();
    defer deleted_sessions_mutex.unlock();
    pruneDeletedSessionsUnlocked();
    const key = try allocator.dupe(u8, sid);
    try deleted_sessions.put(key, time.timestamp());
    pruneDeletedSessionsUnlocked();
}

fn unmarkDeleted(sid: []const u8) void {
    deleted_sessions_mutex.lock();
    defer deleted_sessions_mutex.unlock();
    _ = deleted_sessions.remove(sid);
    pruneDeletedSessionsUnlocked();
}

fn pruneDeletedSessionsUnlocked() void {
    const now = time.timestamp();
    var it = deleted_sessions.iterator();
    var to_remove = ArrayList([]const u8).init(global_allocator);
    defer to_remove.deinit();
    while (it.next()) |entry| {
        if (now - entry.value_ptr.* > DELETED_SESSION_TTL) {
            to_remove.append(entry.key_ptr.*) catch {};
        }
    }
    for (to_remove.items) |k| {
        _ = deleted_sessions.remove(k);
    }
    if (deleted_sessions.count() > MAX_DELETED_SESSIONS) {
        var pairs = ArrayList(struct { key: []const u8, val: i64 }).init(global_allocator);
        defer pairs.deinit();
        var it2 = deleted_sessions.iterator();
        while (it2.next()) |entry| {
            pairs.append(.{ .key = entry.key_ptr.*, .val = entry.value_ptr.* }) catch {};
        }
        std.sort.block(struct { key: []const u8, val: i64 }, pairs.items, {}, struct {
            fn lessThan(_: void, a: struct { key: []const u8, val: i64 }, b: struct { key: []const u8, val: i64 }) bool {
                return a.val < b.val;
            }
        }.lessThan);
        const excess = deleted_sessions.count() - MAX_DELETED_SESSIONS;
        var i: usize = 0;
        while (i < excess and i < pairs.items.len) : (i += 1) {
            _ = deleted_sessions.remove(pairs.items[i].key);
        }
    }
}

fn pruneVideoRequests() void {
    video_requests_mutex.lock();
    defer video_requests_mutex.unlock();
    const now = time.timestamp();
    var to_remove = ArrayList([]const u8).init(global_allocator);
    defer to_remove.deinit();
    var it = video_requests.iterator();
    while (it.next()) |entry| {
        const vr = entry.value_ptr.*;
        const stale_completed = vr.completed_at != null and now - vr.completed_at.? > 120;
        const stale_started = now - vr.started_at > 600;
        if (stale_completed or stale_started) {
            to_remove.append(entry.key_ptr.*) catch {};
        }
    }
    for (to_remove.items) |k| {
        if (video_requests.getPtr(k)) |vrp| {
            vrp.*.deinit();
            global_allocator.destroy(vrp.*);
        }
        _ = video_requests.remove(k);
    }
}

fn evictSessions() void {
    const now = time.timestamp();
    var to_remove = ArrayList([]const u8).init(global_allocator);
    defer to_remove.deinit();
    var it = sessions_map.iterator();
    while (it.next()) |entry| {
        const s = entry.value_ptr.*;
        if (now - s.updated_at > SESSION_TTL) {
            to_remove.append(entry.key_ptr.*) catch {};
        }
    }
    for (to_remove.items) |k| {
        if (sessions_map.getPtr(k)) |sp| {
            sp.*.deinit();
            global_allocator.destroy(sp.*);
        }
        _ = sessions_map.remove(k);
    }
    if (sessions_map.count() > MAX_SESSIONS) {
        var pairs = ArrayList(struct { key: []const u8, updated_at: i64 }).init(global_allocator);
        defer pairs.deinit();
        var it2 = sessions_map.iterator();
        while (it2.next()) |entry| {
            pairs.append(.{ .key = entry.key_ptr.*, .updated_at = entry.value_ptr.*.updated_at }) catch {};
        }
        std.sort.block(struct { key: []const u8, updated_at: i64 }, pairs.items, {}, struct {
            fn lessThan(_: void, a: struct { key: []const u8, updated_at: i64 }, b: struct { key: []const u8, updated_at: i64 }) bool {
                return a.updated_at < b.updated_at;
            }
        }.lessThan);
        const excess = sessions_map.count() - MAX_SESSIONS;
        var i: usize = 0;
        while (i < excess and i < pairs.items.len) : (i += 1) {
            if (sessions_map.getPtr(pairs.items[i].key)) |sp| {
                sp.*.deinit();
                global_allocator.destroy(sp.*);
            }
            _ = sessions_map.remove(pairs.items[i].key);
        }
    }
}

fn generateUUID(allocator: Allocator) ![]u8 {
    var bytes: [16]u8 = undefined;
    std.crypto.random.bytes(&bytes);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    return fmt.allocPrint(allocator, "{x:0>8}-{x:0>4}-{x:0>4}-{x:0>4}-{x:0>12}", .{
        std.mem.readInt(u32, bytes[0..4], .big),
        std.mem.readInt(u16, bytes[4..6], .big),
        std.mem.readInt(u16, bytes[6..8], .big),
        std.mem.readInt(u16, bytes[8..10], .big),
        @as(u48, @intCast(std.mem.readInt(u32, bytes[10..14], .big))) << 16 | std.mem.readInt(u16, bytes[14..16], .big),
    });
}

fn generateHex(allocator: Allocator, n: usize) ![]u8 {
    const bytes = try allocator.alloc(u8, n / 2 + 1);
    defer allocator.free(bytes);
    std.crypto.random.bytes(bytes[0 .. n / 2]);
    const hex = try allocator.alloc(u8, n);
    const hex_chars = "0123456789abcdef";
    var i: usize = 0;
    while (i < n / 2) : (i += 1) {
        hex[i * 2] = hex_chars[bytes[i] >> 4];
        hex[i * 2 + 1] = hex_chars[bytes[i] & 0x0f];
    }
    return hex;
}

