fn urlPercentEncode(allocator: Allocator, input: []const u8) ![]u8 {
    var out = ArrayList(u8).init(allocator);
    for (input) |c| {
        if ((c >= 'A' and c <= 'Z') or (c >= 'a' and c <= 'z') or (c >= '0' and c <= '9') or c == '-' or c == '_' or c == '.' or c == '~') {
