fn sanitizeToolContentForApi(allocator: Allocator, content: []const u8) ![]u8 {
    const stripped = mem.trim(u8, content, " \t\n\r");
    if (stripped.len == 0 or stripped[0] != '{') return allocator.dupe(u8, content);
    if (mem.indexOf(u8, stripped, "\"type\":\"image_generation\"")) |_| {
        if (mem.indexOf(u8, stripped, "\"image_key\"") != null and mem.indexOf(u8, stripped, "\"image_data\"") != null) {
            var out = ArrayList(u8).init(allocator);
            var i: usize = 0;
            var skip = false;
            while (i < stripped.len) {
                if (!skip and mem.startsWith(u8, stripped[i..], "\"image_data\"")) {
                    skip = true;
                    var depth: usize = 0;
                    var found_colon = false;
                    while (i < stripped.len) {
                        if (!found_colon and stripped[i] == ':') {
                            found_colon = true;
                            i += 1;
                            continue;
                        }
                        if (found_colon) {
                            if (stripped[i] == '"') {
                                i += 1;
                                while (i < stripped.len and stripped[i] != '"') {
                                    if (stripped[i] == '\\') i += 1;
                                    i += 1;
                                }
                                i += 1;
                                break;
                            } else if (stripped[i] == '{' or stripped[i] == '[') {
                                depth += 1;
                                i += 1;
                            } else if (stripped[i] == '}' or stripped[i] == ']') {
                                if (depth == 0) break;
                                depth -= 1;
                                i += 1;
                                if (depth == 0) break;
                            } else {
                                i += 1;
                            }
                        } else {
                            i += 1;
                        }
                    }
                    if (i < stripped.len and stripped[i] == ',') i += 1;
                    skip = false;
                    continue;
                }
                try out.append(stripped[i]);
                i += 1;
            }
            return out.toOwnedSlice();
        }
    }
    return allocator.dupe(u8, content);
}

