        const parsed = try std.Uri.parse(url);
        if (parsed.port) |p| break :blk p;
        if (mem.startsWith(u8, url, "https://")) break :blk 443;
        break :blk 80;
    };
    const path = blk: {
        const parsed = try std.Uri.parse(url);
        if (parsed.path.len > 0) break :blk parsed.path else break :blk "/";
    };
